import type { BiomarkerInput, DrugInput, EntityInput, PaperInput, PathwayInput, TargetInput, TermInput, TrialInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * GALLBLADDER CANCER, MOLECULAR LAYER. Facts checked 2026-09-24.
 *
 * The genomic landscape of gallbladder carcinoma as a sourced table (`gallbladderMolecularLandscape`), the regional
 * differences, the premalignant sequence, the pathway view and the immune microenvironment; the biomarker readouts,
 * targets, tests and HER2 medicines that follow from it; and paper records for every landscape paper cited.
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 24 Sept 2026 from the public cBioPortal API (read-only) on the named study id: the
 * count of samples carrying a non-synonymous mutation (or a high-level amplification / deep deletion in the discrete
 * copy-number profile) divided by the study's sequenced (or copy-number) sample list. They are sample-level
 * frequencies for the study as deposited, not the per-patient percentages the paper's own text may quote; where the
 * abstract gives a figure, the abstract's figure is listed first. Nothing is invented and no OncoKB or COSMIC data
 * was used. Abstract text was read from Europe PMC.
 *
 * Cancer id. The corpus cancer record for gallbladder cancer is `gallbladder` (src/data/spikes/nci-rare-other.ts,
 * parent biliary-tract-cancer). If the record is re-keyed as `gallbladder-cancer`, change GALLBLADDER_CANCER_ID and
 * nothing else; every reference in this file goes through it.
 */
export const GALLBLADDER_CANCER_ID = "gallbladder";
const GBC = GALLBLADDER_CANCER_ID;
const asOf = "2026-09-24";

const doi = (d: string) => `https://doi.org/${d}`;
const pubmed = (pmid: string) => `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
const cbio = (study: string) => `https://www.cbioportal.org/study/summary?id=${study}`;

const t = (x: Omit<TermInput, "kind" | "asOf">): TermInput => ({ kind: "term", asOf, ...x });
type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });
/** A partial record for an entity another file owns; arrays append, scalars fill gaps only (see applySpikeSupplements). */
const sup = <T extends EntityInput>(x: { id: string } & Partial<Omit<T, "id" | "kind">>): SpikeSupplement => x as SpikeSupplement;

