// ======================= THE LANDSCAPE TABLE =======================
/**
 * One row per gene and alteration type. `pct` is the headline figure for the prevalence matrix (a number, or a range
 * string like "8-15"); `frequency` spells out every cohort behind it. Agent A's cancer record can import this table.
 */
export type MolecularLandscapeRow = {
  gene: string;
  /** Corpus target id (src/data/targets*.ts); composite targets (idh, brca, mmr, ntrk) stand for their gene families. */
  targetId: string;
  alteration: string;
  /** Headline figure for the prevalence matrix: 0 to 100, or a range string. */
  pct: number | string;
  /** Every frequency with its cohort, size and paper. */
  frequency: string;
  /** Comparison with cholangiocarcinoma or between regions, when a source makes one. */
  contrast?: string;
  sources: Array<{ label: string; url: string }>;
};

