// ======================= REGIONAL DIFFERENCES, PREMALIGNANT SEQUENCE, PATHWAYS, IMMUNE =======================
export const gallbladderRegionalDifferences: Array<{ region: string; finding: string; sources: Array<{ label: string; url: string }> }> = [
  { region: "Chile", finding: "TP53 30%, TSC2 29% and NOTCH1 27% led the 56 Chilean tumours that passed quality control on a 143-gene panel, with actionable variants in ATM, BRCA1/2, EGFR and ERBB2 and an exploratory link between Mapuche ancestry and TP53 mutation (Erices 2025). Among 21 Chilean patients sequenced at MSK, ERBB3 and ARID2 mutations were absent while SMAD4 was mutated in 38% (Narayan 2019). ERBB2 alterations were 9% in 23 Chilean versus 15% in 237 American patients, not significantly different, and gallstones were far commoner in Chile, 85% versus 44% (Mondaca 2024).", sources: [link(SRC.erices2025), link(SRC.narayan2019), link(SRC.mondaca2024)] },
  { region: "India", finding: "376 patients from three Indian institutions were diagnosed a decade younger than international cohorts (median 54 years); TP53 54% and ERBB2 15% led, ARID1A, SMAD4 and CDKN2A were all significantly less altered than in Western and Asian cohorts, and MSI-high (0.6%) and TMB-high (1.3%) were rare (Suryavanshi 2025). PD-L1 on tumour cells was 23% at a 1% cut-off in 174 Indian cases (Neyaz 2018). Chronic Salmonella Typhi carriage is the Indian risk factor with an experimental mechanism (Scanu 2015).", sources: [link(SRC.suryavanshi2025), link(SRC.neyaz2018), link(SRC.scanu2015)] },
  { region: "Japan", finding: "Japanese patients were older (median 72 years), had more well-differentiated tumours and fewer gallstone-associated cancers, lacked ARID1A and PIK3CA mutations and carried a higher mutation count (median 6 versus 4 in the United States) among 81 patients (Narayan 2019). HER2-positive by gastric scoring reached 31.3% of 80 resected gallbladder carcinomas (Hiraoka 2020). In 260 Japanese biliary cancers the APOBEC mutational signature was heaviest in gallbladder and extrahepatic tumours (Nakamura 2015).", sources: [link(SRC.narayan2019), link(SRC.hiraoka2020), link(SRC.nakamura2015)] },
  { region: "China", finding: "In 57 tumour-normal pairs from Shanghai, C-to-T mutations at TCN sites dominated, TP53 (47.1%), KRAS (7.8%) and ERBB3 (11.8%) were significantly mutated and the ErbB pathway was altered in 36.8% with worse survival (Li 2014).", sources: [link(SRC.li2014)] },
  { region: "United States and Europe", finding: "244 MSK-IMPACT samples: TP53 63%, CDKN2A 21%, ERBB2 15%, KRAS 11%, actionable alterations in 35% of patients, no difference between primaries and metastases (Giraldo 2022). Western cholangiocarcinoma MSI-high 1.3% (Goeppert 2019); Western gallbladder PD-L1 TPS 1% or more in 14.7% (Albrecht 2021). Across 167 tumours from Korea, India and Chile, ELF3, EHF, CTNNB1, APC, NSD1, KAT8, STK11 and NFE2L2 were newly significant, with recurrent KEAP1/NFE2L2 and Wnt alterations (Pandey 2020).", sources: [link(SRC.giraldo2022), link(SRC.goeppert2019), link(SRC.albrecht2021), link(SRC.pandey2020)] },
];

export const gallbladderPremalignantSequence = {
  summary: "Two routes lead to invasive gallbladder carcinoma. The common one is flat: chronic irritation from stones or infection produces metaplasia, then dysplasia, then carcinoma in situ, then invasion, and metaplasia, dysplasia and carcinoma in situ are found in the mucosa next to 66%, 81.3% and 69% of cancers (Roa 2006); the age gradient from dysplasia to advanced carcinoma puts the sequence at roughly 10 to 15 years (Roa 1996, Roa 2006). The rare route is a raised adenoma or papillary neoplasm, now grouped as intracholecystic papillary-tubular neoplasm (ICPN) when 1 cm or larger: adenomas were found in 0.14% of cholecystectomies and adenomatous remnants next to fewer than 3% of early carcinomas (Roa 2006), yet 55% of 123 ICPNs carried invasive carcinoma and the associated carcinomas fared better than pancreatobiliary-type cancers, 60% versus 27% three-year survival (Adsay 2012). Exome sequencing of co-existing low-grade BilIN (adenoma), high-grade BilIN and carcinoma from the same gallbladders found CTNNB1 mutations central, ageing the main source of mutations, and two evolutionary paths: the classic adenoma or dysplasia to carcinoma sequence, and an early-diverging path in which extensive loss of heterozygosity creates a cancerous niche independent of the visible BilIN (Lin 2021). Salmonella enterica transforms predisposed gallbladder organoids and fibroblasts through effector-driven MAPK and AKT activation, with TP53 mutation and c-MYC amplification (Scanu 2015); Salmonella Typhi carriage carries a summary relative risk of 4.6 for anti-Vi antibody and 5.0 for bile or stool culture across more than 1,000 cases (Koshiol 2016).",
  sources: [link(SRC.roa2006), link(SRC.roa1996), link(SRC.adsay2012), link(SRC.lin2021), link(SRC.scanu2015), link(SRC.koshiol2016)],
};

