export const gallbladderImmuneMicroenvironment = {
  summary: "PD-L1 on tumour cells ranges from 14.7% (TPS 1% or more, 131 Western cases; Albrecht 2021) to 23% (SP263, 174 Indian cases; Neyaz 2018), and to 98% in a 47-case United States series using a different antibody and scoring (Patil 2021), so the clone, the score and the cut-off matter more than the population. PD-L1 above 10% TPS was an independent negative prognosticator in the Western series and went with poor differentiation and denser CD4, CD8 and PD-1-positive infiltrates; TIGIT was expressed on scattered immune cells in 14.8% of cases alongside its ligand CD155 (Albrecht 2021). PD-1-positive tumour-infiltrating lymphocytes were present in 78.7% of adenocarcinomas; in tumours under 3 cm, stromal CD3 above 115 or CD8 above 45 per high-power field went with better survival, whereas in tumours of 3 cm or more PD-1-positive infiltrates and high CD8 went with worse survival (Patil 2021). The 190-patient integrative study found two poor-survival transcriptomic subtypes marked by myeloid-derived suppressor cell accumulation, extensive desmoplasia, hypoxia and T-cell dysfunction, and one good-survival subtype with the opposite features (Nepal 2021). MSI-high cholangiocarcinomas carried more CD8, FOXP3 and CD20 cells and higher MHC class I (Goeppert 2019). The first-line immunotherapy approvals (durvalumab, pembrolizumab with gemcitabine and cisplatin) were unselected and no biliary label carries a PD-L1 threshold.",
  sources: [link(SRC.albrecht2021), link(SRC.neyaz2018), link(SRC.patil2021), link(SRC.nepal2021), link(SRC.goeppert2019)],
};

