/** Target supplements derived from the landscape table: a prevalence row per (gene, alteration) plus the cancer link. */
const targetSupplements: SpikeSupplement[] = (() => {
  const byTarget = new Map<string, MolecularLandscapeRow[]>();
  for (const r of landscapeTargetRows) byTarget.set(r.targetId, [...(byTarget.get(r.targetId) ?? []), r]);
  return [...byTarget.entries()].map(([targetId, rows]) => sup<TargetInput>({
    id: targetId,
    cancers: [GBC],
    prevalence: rows.map((r) => ({ cancerId: GBC, pct: r.pct, measure: r.alteration, source: r.sources[0].url, note: r.frequency })),
    whereFound: rows.map((r) => `Gallbladder cancer: ${r.alteration.toLowerCase()} ${typeof r.pct === "number" ? `about ${r.pct}%` : `${r.pct}%`}`),
    keyPapers: [...new Set(rows.flatMap((r) => r.sources.map((s) => PAPER_BY_URL.get(s.url)).filter((x): x is string => !!x)))],
  }));
})();

const her2GallbladderNote = "Gallbladder cancer, amplification versus mutation: ERBB2 alterations were present in 14% of 260 patients, as 8% amplification alone, 4% mutation alone, 1.5% both and 0.4% fusion (Mondaca 2024, MSK-IMPACT), and in 15% of 376 Indian patients with about 8% amplification and an S310F/Y hotspot (Suryavanshi 2025). Only the amplified tumours are seen by IHC and ISH, which is what the zanidatamab label tests for (IHC 3+); the extracellular S310 and kinase-domain mutations need sequencing and are not covered by that label. Protein positivity depends on the scoring rule: 31.3% of 80 resected Japanese gallbladder carcinomas by the gastric guideline (Hiraoka 2020), 12.8% of 187 Chilean cases by breast criteria (Roa 2014), 9.4% of 53 by HERIZON-BTC-01 criteria (Angerilli 2026). ERBB2-driven biliary tumours can lose ERBB2 at progression (Cowzer 2026).";

